optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/xml.rs b/tools/bot-evaluation/src/xml.rs
index 3accb4ad..7806d10d 100644
--- a/tools/bot-evaluation/src/xml.rs
+++ b/tools/bot-evaluation/src/xml.rs
@@ -190,7 +190,9 @@ fn emit(writer: &mut Writer<Vec<u8>>, name: &str, value: &Value) -> Result<()> {
         }
         writer.write_event(Event::Text(BytesText::new(&text)))?;
     }
-    writer.write_event(Event::End(BytesEnd::new(name)))?;
+    writer.get_mut().extend_from_slice(b"</");
+    writer.get_mut().extend_from_slice(name.as_bytes());
+    writer.get_mut().push(b'>');
     Ok(())
 }
 pub fn fragment(name: &str, value: &Value) -> Result<Vec<u8>> {
